from pathlib import Path
root=Path.cwd()
def rd(path):
    p=root/path
    if not p.exists(): raise SystemExit(f"v8.1 missing {path}")
    return p.read_text(encoding="utf-8")
def wr(path,text): (root/path).write_text(text,encoding="utf-8")
def one(text,old,new,label):
    if old not in text: raise SystemExit(f"v8.1 marker missing: {label}")
    return text.replace(old,new,1)

p="src/ui/player_panel.rs"; t=rd(p)
if "    Comparison,\n" not in t:
    t=one(t,"    Languages,\n}","    Languages,\n    Comparison,\n    CareerPlans,\n    SwapPlayer,\n    CloneCenter,\n    WorkPermit,\n    Promises,\n    Retirement,\n    ScoutInfo,\n}","player tab expansion")
lang_arm='        PlayerTab::Languages => {\n            egui::ScrollArea::vertical()\n                .id_salt("player_languages_v79")\n                .show(ui, |ui| show_languages_panel(ui, player));\n        }\n'
if "PlayerTab::Comparison =>" not in t:
    extra=lang_arm+'        PlayerTab::Comparison => {\n            egui::ScrollArea::vertical().id_salt("player_compare_v81").show(ui, |ui|\n                show_inline_comparison(schemas,today,ui,player,entity_cache));\n        }\n        PlayerTab::CareerPlans => {\n            egui::ScrollArea::vertical().id_salt("player_career_v81").show(ui, |ui|\n                show_career_planner(schemas,today,ui,player));\n        }\n        PlayerTab::SwapPlayer => {\n            egui::ScrollArea::vertical().id_salt("player_swap_v81").show(ui, |ui|\n                show_swap_player(ui,player,entity_cache));\n        }\n        PlayerTab::CloneCenter => {\n            egui::ScrollArea::vertical().id_salt("player_clone_v81").show(ui, |ui|\n                show_clone_center(schemas,ui,player,addr,entity_cache,&mut edits));\n        }\n        PlayerTab::WorkPermit => {\n            egui::ScrollArea::vertical().id_salt("player_workpermit_v81").show(ui, |ui|\n                show_work_permit(ui,player,entity_cache));\n        }\n        PlayerTab::Promises => {\n            egui::ScrollArea::vertical().id_salt("player_promises_v81").show(ui, |ui|\n                show_promises(schemas,ui,player,addr,&mut edits));\n        }\n        PlayerTab::Retirement => {\n            egui::ScrollArea::vertical().id_salt("player_retirement_v81").show(ui, |ui|\n                show_retirement(schemas,today,ui,player));\n        }\n        PlayerTab::ScoutInfo => {\n            egui::ScrollArea::vertical().id_salt("player_scout_v81").show(ui, |ui|\n                show_scout_info(schemas,today,ui,player,entity_cache));\n        }\n'
    t=one(t,lang_arm,extra,"player match arms")
if "fn player_category_score_v81(" not in t:
    marker="fn push_max_category_edits(\n"; idx=t.find(marker)
    if idx<0: raise SystemExit("v8.1 player helper marker missing")
    funcs='fn player_category_score_v81<T: crate::fields::HasSubRecords>(schemas:&\'static fields::VersionedSchemas, obj:&T, raw:&[u8], category:Category)->f32{\n    let mut total=0.0; let mut n=0usize;\n    for f in schemas.fields_for_category(Entity::Player,category){\n        if let Some(v)=fields::read_field_u8(obj,raw,f){ if (1..=20).contains(&v){total+=v as f32;n+=1;} }\n    }\n    if n==0{0.0}else{total/n as f32}\n}\n\nfn player_primary_position_v81(schemas:&\'static fields::VersionedSchemas, raw:&[u8])->String{\n    let mut best:(String,u8)=("—".into(),0);\n    for f in schemas.fields_for_category(Entity::Player,Category::Positions){\n        if let Some(loc)=f.offset { let off=loc.offset() as usize; if let Some(&b)=raw.get(off){let v=loc.decode_u8(b); if v>best.1{best=(f.label.replace("Position: ",""),v);}} }\n    }\n    best.0\n}\n\nfn select_cached_player_v81<\'a>(ui:&mut egui::Ui,player:&PlayerRecord,cache:Option<&\'a crate::cache::EntityCache>,id_tag:&\'static str,exclude_same_club:bool)->Option<&\'a crate::cache::CachedPlayer>{\n    let cache=cache?;\n    let search_id=egui::Id::new((id_tag,"search",player.addr));\n    let selected_id=egui::Id::new((id_tag,"selected",player.addr));\n    let mut q=ui.ctx().data_mut(|d|d.get_temp::<String>(search_id).unwrap_or_default());\n    let selected_addr=ui.ctx().data(|d|d.get_temp::<u64>(selected_id));\n    ui.horizontal(|ui|{ui.label("Player:");if ui.add_sized([280.0,22.0],egui::TextEdit::singleline(&mut q).hint_text("Search player…")).changed(){ui.ctx().data_mut(|d|d.insert_temp(search_id,q.clone()));}});\n    if q.trim().len()>=2{\n        let needle=q.to_lowercase(); let current_club=cache.players.iter().find(|p|p.addr==player.addr).and_then(|p|p.club_id); let mut shown=0;\n        for p in cache.players.iter().filter(|p|p.addr!=player.addr&&p.name.to_lowercase().contains(&needle)){\n            if exclude_same_club&&p.club_id==current_club{continue;}\n            let club=p.club_id.and_then(|id|cache.club_names.get(&id)).cloned().unwrap_or_else(||"Free / unknown".into());\n            if ui.selectable_label(selected_addr==Some(p.addr),format!("{} • {} • CA {} / PA {}",p.name,club,p.ca,p.pa)).clicked(){ui.ctx().data_mut(|d|d.insert_temp(selected_id,p.addr));q.clear();ui.ctx().data_mut(|d|d.insert_temp(search_id,String::new()));}\n            shown+=1;if shown>=18{break;}\n        }\n    }\n    let addr=ui.ctx().data(|d|d.get_temp::<u64>(selected_id))?;\n    cache.players.iter().find(|p|p.addr==addr)\n}\n\nfn show_inline_comparison(schemas:&\'static fields::VersionedSchemas,today:Option<crate::game_date::GameDate>,ui:&mut egui::Ui,player:&PlayerRecord,cache:Option<&crate::cache::EntityCache>){\n    ui.horizontal_wrapped(|ui|{ui.heading("Comparison");ui.label(egui::RichText::new("ELEMENT v8.1 • LIVE DATABASE COMPARE").strong().color(egui::Color32::from_rgb(96,178,255)));});\n    ui.label(egui::RichText::new("Select any loaded player. This page compares the same independently mapped FM27 fields used by the editor; no scouting fog is fabricated.").weak());ui.add_space(6.0);\n    let Some(other)=select_cached_player_v81(ui,player,cache,"element_compare",false) else{ui.label("Search and select a player to compare.");return;};\n    let age_me=crate::ui::entity_header::age(schemas,today,&player.raw,"p_dob").map(|v|v.to_string()).unwrap_or_else(||"—".into());\n    let age_other=today.and_then(|d|(other.dob_year>0&&d.year>=other.dob_year).then_some(d.year-other.dob_year)).map(|v|v.to_string()).unwrap_or_else(||"—".into());\n    egui::Grid::new(("element_compare_grid",player.addr,other.addr)).striped(true).spacing([18.0,6.0]).show(ui,|ui|{\n        ui.strong("Metric");ui.strong(player.name.as_deref().unwrap_or("Current"));ui.strong(&other.name);ui.end_row();\n        for (label,a,b) in [\n            ("Age",age_me,age_other),("CA",player.field_u16("p_ca").map(|v|v.to_string()).unwrap_or_else(||"—".into()),other.ca.to_string()),\n            ("PA",player.field_u16("p_pa").map(|v|v.to_string()).unwrap_or_else(||"—".into()),other.pa.to_string()),\n            ("Position",player_primary_position_v81(schemas,&player.raw),player_primary_position_v81(schemas,&other.raw)),\n        ]{ui.label(label);ui.label(a);ui.label(b);ui.end_row();}\n        for (label,cat) in [("Technical",Category::Technical),("Mental",Category::Mental),("Physical",Category::Physical),("Set Pieces",Category::SetPieces),("Goalkeeping",Category::Goalkeeping)]{\n            ui.label(label);ui.label(format!("{:.1}/20",player_category_score_v81(schemas,player,&player.raw,cat)));ui.label(format!("{:.1}/20",player_category_score_v81(schemas,other,&other.raw,cat)));ui.end_row();\n        }\n    });\n    ui.add_space(8.0);if ui.button("OPEN COMPARED PLAYER").clicked(){crate::ui::navigation::request_player_target(ui,other.addr,other.index,other.name.clone());}\n}\n\nfn show_career_planner(schemas:&\'static fields::VersionedSchemas,today:Option<crate::game_date::GameDate>,ui:&mut egui::Ui,player:&PlayerRecord){\n    ui.horizontal_wrapped(|ui|{ui.heading("Career Plans");ui.label(egui::RichText::new("ELEMENT v8.1 • CAREER PLANNER").strong().color(egui::Color32::from_rgb(96,178,255)));});\n    let age=crate::ui::entity_header::age(schemas,today,&player.raw,"p_dob").unwrap_or(0);let ca=player.field_u16("p_ca").unwrap_or(0);let pa=player.field_u16("p_pa").unwrap_or(ca);let gap=pa.saturating_sub(ca);\n    let route=if age<=21&&gap>=15{"Development loan / controlled first-team minutes"}else if gap>=10{"High-upside development role"}else if age>=30{"Peak/late-career contract management"}else{"First-team consolidation"};\n    egui::Frame::group(ui.style()).inner_margin(10.0).show(ui,|ui|{ui.strong("Element derived plan");field_widget::info_label(ui,"Age",age);field_widget::info_label(ui,"CA / PA",format!("{ca} / {pa}"));field_widget::info_label(ui,"Growth headroom",gap);field_widget::info_label_wrapped(ui,"Recommended pathway",route);});\n    ui.add_space(8.0);ui.strong("Native FM career-plan record");ui.label("FM27 IL2CPP exposes Career Plans views, but the underlying player record/vector has not been independently mapped. Element does not invent a native career plan write.");\n}\n\nfn show_swap_player(ui:&mut egui::Ui,player:&PlayerRecord,cache:Option<&crate::cache::EntityCache>){\n    ui.horizontal_wrapped(|ui|{ui.heading("Swap Player");ui.label(egui::RichText::new("ELEMENT v8.1 • TRANSACTIONAL TEAM SWAP").strong().color(egui::Color32::from_rgb(96,178,255)));});\n    ui.label(egui::RichText::new("Swaps two existing contracted players between their current teams by replacing roster entries in-place, then updates both team/contract ownership pointers and validates read-back. No transfer fee or native Inbox/history is created.").weak());\n    if player.contract_addr.is_none(){ui.colored_label(egui::Color32::YELLOW,"Current player has no mapped contract; swap unavailable.");return;}\n    let Some(other)=select_cached_player_v81(ui,player,cache,"element_swap",true) else{ui.label("Select a player at another club.");return;};\n    ui.label(format!("Selected: {} • CA {} / PA {}",other.name,other.ca,other.pa));\n    let ack_id=egui::Id::new(("element_swap_ack",player.addr));let mut ack=ui.ctx().data(|d|d.get_temp::<bool>(ack_id).unwrap_or(false));\n    if ui.checkbox(&mut ack,"I made a save backup and understand this is a direct non-native swap").changed(){ui.ctx().data_mut(|d|d.insert_temp(ack_id,ack));}\n    if ui.add_enabled(can_edit(ui)&&ack,egui::Button::new("↔ SWAP PLAYERS • LIVE")).clicked(){\n        ui.ctx().data_mut(|d|d.insert_temp(egui::Id::new("element_v81_swap_players_request"),(player.addr,player.person_shift,player.contract_addr.unwrap(),other.addr,other.index)));\n    }\n}\n\n'
    t=t[:idx]+funcs+t[idx:]
wr(p,t)
print("Element v8.1b1 player navigation/compare/swap UI applied.")
